/**
 * 未確定（uncertain）題目的**交付路徑**（Sprint 8.0 發行前審計）。
 *
 * 背景：Sprint 7.9 為品質閘門加上第三種結果——「未確定」（`questions.teacher_confirmation_required`）。
 * 題目仍然保留在題庫，但自動發布被暫緩，須由教師確認。tests/publication-safety.test.ts 已把
 * 三條**發布**路徑（`changeQuestionStatus`／`recordAutoValidationAndPublish`／
 * `publishAutoGeneratedQuestion`）及題庫組題寫成可執行契約。
 *
 * 本檔補上兩條當時沒有覆蓋的**學生交付路徑**（2026-10-16 審計確認的缺陷）：
 *
 *   1. `questionSource: "ai"`（學生自行觸發的即時生成）——`collect()` 在被呼叫前就讀取
 *      `withheld`，令「第一輪生成即有未確定題目」時擲出 TDZ `ReferenceError`：整次練習以
 *      500 失敗，而不是抽起該題並保留其他題目。
 *   2. 題庫不足時的即時補題（`questionSource: "bank"`）——直接採用生成結果，令「自動發布已
 *      暫緩」的題目被寫進練習快照送到學生面前，繞過三條發布路徑的關卡。
 *
 * 兩條路徑都以**真實的生成→驗證→閘門→組題**流程測試：provider 只是把 HTTP 回應換成
 * 確定性的合成題目（`vi.stubGlobal("fetch", …)`，與 tests/llm-provider.test.ts 同一手法），
 * 沒有呼叫任何外部 API。
 */
import { afterEach, beforeAll, describe, expect, it, vi } from "vitest";

import type { MaterialUnit } from "@/server/llm/provider";

import { freshTestDatabasePath } from "./test-database";
import { openDocumentForStudents } from "./material-distribution";
import { importTestPilotMaterial } from "./fixtures/pilot-material";
const testDbPath = freshTestDatabasePath("practice-withheld-delivery");
process.env.APP_DATABASE_PATH = testDbPath;
// 假 provider：沒有真實 API key，只有一個被 stub 的 HTTP 回應（見下方 fetchStub）
process.env.LLM_PROVIDER = "openai-compatible";
process.env.LLM_API_KEY = "test-key-not-a-secret";
process.env.LLM_BASE_URL = "https://llm.test.invalid";
process.env.LLM_MODEL = "test-model";
delete process.env.K_SERVICE;

type PracticeService = typeof import("@/server/services/practice-service");
type PracticeRepo = typeof import("@/server/repositories/practice");
type QuestionsRepo = typeof import("@/server/repositories/questions");
type MaterialsRepo = typeof import("@/server/repositories/materials");
type MaterialUnits = typeof import("@/server/services/material-units");
type TextUtils = typeof import("@/server/materials/text-utils");
type TopicsRepo = typeof import("@/server/repositories/topics");
type Seed = typeof import("@/server/seed");

let practice: PracticeService;
let practiceRepo: PracticeRepo;
let questionsRepo: QuestionsRepo;
let materialsRepo: MaterialsRepo;
let materialUnits: MaterialUnits;
let textUtils: TextUtils;
let topicsRepo: TopicsRepo;
let seed: Seed;

const TOPIC = "topic-5";
const LEARNER = "withheld-delivery-learner";

/** 一個「解釋只是重複答案」的合成題目：閘門必須判定為需教師確認 */
const UNCERTAIN_STEM = "工業革命期間城市人口有甚麼變化？";

interface MaterialFact {
  blockId: string;
  excerpt: string;
}

/**
 * 測試用的分節（在 beforeAll 決定）：必須有學生可用教材（才能即時生成），
 * 而且展開後（與 createPractice 一致）的已發布題目愈少愈好，令題庫路徑一定要
 * 即時補題（內建示範題庫亦有題目，若不選這種分節，補題永遠不會發生）。
 */
let sectionId: string;
let expandedSectionIds: string[] = [];
let fact: MaterialFact;
let fact2: MaterialFact;

/**
 * 合成題目：一條乾淨的選擇題（標準答案逐字見於教材）＋一條未確定的選擇題
 * （解釋只是重複答案 → 閘門判為需教師確認，暫緩自動發布）。
 */
function syntheticQuestions() {
  return [
    {
      questionType: "mc",
      difficulty: "basic",
      question: "以下哪一項描述最符合這個課題的內容？",
      options: [fact.excerpt, "與本題無關的敘述甲", "與本題無關的敘述乙", "與本題無關的敘述丙"],
      correctAnswerIndex: 0,
      correctAnswer: fact.excerpt,
      explanation: `課文原文這樣說明：${fact.excerpt}`,
      knowledgePoint: "工業發展與城市人口",
      sourceExcerpt: fact.excerpt,
      sourceBlockIds: [fact.blockId],
      gradingPoints: [],
    },
    {
      questionType: "mc",
      difficulty: "basic",
      question: UNCERTAIN_STEM,
      options: [fact2.excerpt, "與本題無關的敘述丁", "與本題無關的敘述戊", "與本題無關的敘述己"],
      correctAnswerIndex: 0,
      correctAnswer: fact2.excerpt,
      explanation: fact2.excerpt,
      knowledgePoint: "工業革命期間的城市變化",
      sourceExcerpt: fact2.excerpt,
      sourceBlockIds: [fact2.blockId],
      gradingPoints: [],
    },
  ];
}

/** 假的 chat/completions 回應：只把合成題目包成 OpenAI 相容格式，不進行任何網路呼叫 */
function fetchStub(): typeof fetch {
  return (async () =>
    new Response(
      JSON.stringify({
        choices: [{ message: { content: JSON.stringify({ questions: syntheticQuestions() }) } }],
        usage: { prompt_tokens: 100, completion_tokens: 50 },
      }),
      { status: 200, headers: { "content-type": "application/json" } },
    )) as unknown as typeof fetch;
}

function setupInput(overrides: {
  questionSource: "ai" | "bank";
  questionCount: number;
  questionTypes?: ("mc" | "fill")[];
}) {
  return {
    learnerId: LEARNER,
    topicId: TOPIC,
    sectionIds: [sectionId],
    questionTypes: overrides.questionTypes ?? (["mc", "fill"] as ("mc" | "fill")[]),
    difficulty: "basic" as const,
    questionCount: overrides.questionCount,
    mode: "standard" as const,
    questionSource: overrides.questionSource,
    sourceSessionId: null,
  };
}

beforeAll(async () => {
  practice = await import("@/server/services/practice-service");
  practiceRepo = await import("@/server/repositories/practice");
  questionsRepo = await import("@/server/repositories/questions");
  materialsRepo = await import("@/server/repositories/materials");
  materialUnits = await import("@/server/services/material-units");
  textUtils = await import("@/server/materials/text-utils");
  topicsRepo = await import("@/server/repositories/topics");
  seed = await import("@/server/seed");

  seed.ensureBootstrap();
  await importTestPilotMaterial();
  for (const block of materialsRepo.listGroundingBlocksForSections(TOPIC, [])) {
    openDocumentForStudents(materialsRepo, block.documentId);
  }

  // 選一個「有學生可用教材、已發布題目最少」的分節：即時生成可運作，
  // 而題庫路徑只需再補一題（見檔頭說明）。
  const candidateSections = topicsRepo.listSections(TOPIC).map((section) => section.id);
  let best: { candidate: string; expanded: string[]; count: number; units: MaterialUnit[] } | null =
    null;
  for (const candidate of candidateSections) {
    // 與 createPractice 一樣展開子分節：題庫組題用的是展開後的清單，
    // 只檢查分節本身會漏掉子分節的已發布題目（內建示範題庫就散落在子分節）。
    const expanded = topicsRepo.expandSectionIds(TOPIC, [candidate]);
    const units = materialUnits.buildMaterialUnits(TOPIC, expanded, { audience: "student" });
    if (units.length === 0) continue;
    const published = questionsRepo
      .listQuestions({ topicId: TOPIC, sectionIds: expanded, statuses: ["published"] })
      .filter((question) => question.questionType === "mc" || question.questionType === "fill");
    if (best === null || published.length < best.count) {
      best = { candidate, expanded, count: published.length, units };
    }
  }
  if (best === null) throw new Error("課題5找不到有學生可用教材的測試分節");

  sectionId = best.candidate;
  expandedSectionIds = best.expanded;
  // 節錄必須逐字出自**學生可用**的教材單位（生成時用的正是這一組），
  // 因此直接由 buildMaterialUnits 的輸出取句子，而不是由原始段落文字推測。
  const facts: MaterialFact[] = [];
  for (const unit of best.units) {
    // 第二個測試句子必須來自另一個段落，而且該段落沒有明確年份
    // （用於測試「題目要求準確年份但教材沒有」的未確定判定）。
    if (facts.length === 1 && (unit.blockId === facts[0]!.blockId || /\d/.test(unit.text))) continue;
    const sentence = textUtils
      .splitSentences(unit.text)
      .map((part) => part.trim())
      .find(
        (part) => part.length >= 16 && part.length <= 40 && !/\d/.test(part) && !part.includes("＿"),
      );
    if (sentence === undefined) continue;
    facts.push({ blockId: unit.blockId, excerpt: sentence });
    if (facts.length === 2) break;
  }
  if (facts.length < 2) throw new Error("課題5的學生可用教材找不到合適的測試句子");
  fact = facts[0]!;
  fact2 = facts[1]!;
});

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("學生即時生成（questionSource: ai）", () => {
  it("未確定的題目不會進入練習，其他題目照常提供，而且不會令整次練習失敗", async () => {
    vi.stubGlobal("fetch", fetchStub());

    const assembled = await practice.createPractice(setupInput({ questionSource: "ai", questionCount: 2 }));

    const delivered = practiceRepo.getSessionQuestions(assembled.session.id);
    // 未確定的題目被抽起（修復前：第一輪生成即擲出 ReferenceError，整次練習 500）
    expect(delivered.some((question) => question.teacherConfirmationRequired)).toBe(false);
    expect(delivered.some((question) => question.question === UNCERTAIN_STEM)).toBe(false);
    // 其他題目不受影響：乾淨的選擇題仍然可以練習
    expect(delivered.some((question) => question.questionType === "mc")).toBe(true);
    // 學生如實得知有題目被抽起並交教師確認
    expect(assembled.notice ?? "").toContain("未確定");
    // 學生端的題目資料不含答案欄位（未作答前不會洩露）
    const serialised = JSON.stringify(assembled.questions);
    expect(serialised).not.toContain("correctAnswer");
    expect(serialised).not.toContain("explanation");
    expect(serialised).not.toContain("sourceExcerpt");
  });

  it("只有未確定題目時：練習如實失敗（502），不會把題目交給學生", async () => {
    vi.stubGlobal("fetch", fetchStub());

    // 只要求填充題：合成的選擇題會在驗證階段被丟棄（題型不在要求之內），
    // 結果沒有可用題目 → 必須失敗並如實說明，而不是照樣交付。
    await expect(
      practice.createPractice(
        setupInput({ questionSource: "ai", questionCount: 1, questionTypes: ["fill"] }),
      ),
    ).rejects.toThrow(/未能為所選主題生成題目/);
  });
});

describe("題庫不足時的即時補題（questionSource: bank）", () => {
  it("補題產生的未確定題目不會被寫進練習快照", async () => {
    const { blockId, excerpt } = fact;
    // 題庫只有 1 題已發布的乾淨題目，要求 2 題 → 觸發即時補題
    questionsRepo.insertQuestion({
      id: "q-withheld-bank-clean",
      topicId: TOPIC,
      sectionId,
      questionType: "mc",
      difficulty: "basic",
      question: "工業化令城市出現甚麼變化？",
      options: [excerpt, "人口全面減少", "農業完全消失", "城市不再擴張"],
      correctAnswer: excerpt,
      acceptedAnswers: [],
      explanation: `課文說明：${excerpt}`,
      knowledgePoint: "工業化與城市",
      sourceExcerpt: excerpt,
      sourceLocation: "合成測試用位置",
      sourceBlockIds: [blockId],
      gradingPoints: [],
      origin: "material-ai",
      status: "published",
      sourceVerified: true,
      qualityWarnings: [],
      skill: null,
      revision: 1,
      autoValidatedAt: null,
      autoValidatedRevision: null,
      autoValidatedFingerprint: null,
      teacherConfirmationRequired: false,
      createdAt: "2026-10-16T00:00:00.000Z",
    });

    vi.stubGlobal("fetch", fetchStub());

    // 要求比題庫現有題目多一題 → 一定會走到即時補題（questionCount 上限為 30）
    const bankCount = questionsRepo
      .listQuestions({ topicId: TOPIC, sectionIds: expandedSectionIds, statuses: ["published"] })
      .filter(
        (question) =>
          (question.questionType === "mc" || question.questionType === "fill") &&
          !question.teacherConfirmationRequired,
      ).length;
    expect(bankCount).toBeLessThan(30);

    const assembled = await practice.createPractice(
      setupInput({ questionSource: "bank", questionCount: bankCount + 1 }),
    );

    const delivered = practiceRepo.getSessionQuestions(assembled.session.id);
    // 修復前：補題直接採用生成結果，未確定的題目會出現在練習快照並送到學生面前
    expect(delivered.some((question) => question.question === UNCERTAIN_STEM)).toBe(false);
    expect(delivered.map((question) => question.id)).toContain("q-withheld-bank-clean");
    expect(assembled.notice ?? "").toContain("未確定");

    // 補題寫入題庫的題目仍然保留（草稿），教師可在「題目管理」看到並處理
    const held = questionsRepo
      .listQuestions({ topicId: TOPIC })
      .filter((question) => question.teacherConfirmationRequired);
    expect(held.length).toBeGreaterThan(0);
    expect(held.every((question) => question.status === "draft")).toBe(true);
    expect(held.some((question) => question.question === UNCERTAIN_STEM)).toBe(true);
  });
});
